import{e as t,ab as a,a1 as o,m as n,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const b=JSON.parse('{"title":"Monthly Updates [December]","description":"December 2025 updates","frontmatter":{"title":"Monthly Updates [December]","description":"December 2025 updates","date":"2025-12-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/dec-2025.md","filePath":"posts/dec-2025.md"}'),l={name:"posts/dec-2025.md"};function d(h,e,p,f,m,g){const r=a("Post");return o(),n("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added new section for <a href="https://fmhy.net/image-tools#photography-cameras" target="_blank" rel="noreferrer">Photography / Cameras</a>.</p></li><li><p>Added new section for <a href="https://fmhy.net/image-tools#_3d-printing" target="_blank" rel="noreferrer">3D Printing / Printers</a>.</p></li><li><p>Re-ordered <a href="https://fmhy.net/ai#ai-benchmarks" target="_blank" rel="noreferrer">AI Benchmarks</a>, starred Kaggle Benchmarks, removed ones with dated testing, and added a subsection for <a href="https://fmhy.net/ai#specialized-benchmarks" target="_blank" rel="noreferrer">Specialized Benchmarks</a>. <a href="https://i.ibb.co/5xY36Pk5/Untitled.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/NuIHGhC.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Re-ordered and cleaned up ugly formatting in <a href="https://fmhy.net/developer-tools#hosting-tools" target="_blank" rel="noreferrer">Hosting Tools</a>. <a href="https://i.ibb.co/21g23vSy/Untitled.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/G6sJPo1.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Moved <a href="https://fmhy.net/internet-tools#browser-startpages" target="_blank" rel="noreferrer">Browser Startpages</a> + <a href="https://fmhy.net/internet-tools#custom-new-tab-pages" target="_blank" rel="noreferrer">Custom New Tab Pages</a> out of storage into their own sections.</p></li><li><p>Brought back the <a href="https://fmhy.github.io/FMHY-SafeGuard/" target="_blank" rel="noreferrer">Website</a> for FMHY SafeGuard.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">AnimeX</a> in Anime Streaming. Feature-rich, solid sources, big library, nice UI, and has forums.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Bing Image Creator</a> in Image Gen. Gives 200 daily, has good editing, and seems to be the best way to use GPT Image 1 as of now.</p></li><li><p>Starred <a href="https://fmhy.net/video#android-tv" target="_blank" rel="noreferrer">TizenTube Cobalt</a> in Android TV. Ad-free YouTube app, updated often, has SponsorBlock support, and uses the official YouTube UI.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-sports" target="_blank" rel="noreferrer">Watch Footy</a> in Live Sports. Solid sources, nice UI, and lots of events.</p></li><li><p>Starred <a href="https://fmhy.net/video-tools#live-streaming" target="_blank" rel="noreferrer">Streamer.bot</a> in Live Streaming Tools. <a href="https://streamer.bot/features" target="_blank" rel="noreferrer">Feature-rich</a> live stream manager, compatible w/ OBS, Streamlabs, etc.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#roblox-tools" target="_blank" rel="noreferrer">RoSeal</a> in Roblox Tools. Improves the Roblox website and adds nearly 200 extra features.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-reading" target="_blank" rel="noreferrer">Voice</a> in Android Audiobook Players. Open-source, multi-format, has cover fetch, and a nice minimal design.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#productivity-trackers" target="_blank" rel="noreferrer">Loop Habit Tracker</a> in Mobile Productivity. Open-source, has sticky notifications, and better limits than most free options.</p></li><li><p>Re-starred <a href="https://fmhy.net/gaming#rom-sites" target="_blank" rel="noreferrer">CDRomance</a> in ROM Sites as it&#39;s made a comeback. Note that RetroGamingTalk accounts will work on CDRomance.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed Anadius as they&#39;ve <a href="https://i.ibb.co/TD9kRCR3/image.png" target="_blank" rel="noreferrer">decided to step down</a> / <a href="https://i.imgur.com/2Xk8Jor.png" target="_blank" rel="noreferrer">2</a>. It may be re-added in the future if someone new steps up to maintain it.</p></li><li><p>Removed ContextSearch as it&#39;s been removed by Firefox. It seems to be causing issues, and in some cases flooding sites with requests. We&#39;re unsure if it&#39;s purposefully malicious or a mistake by its developer, but regardless, it&#39;s recommended to remove it and try other options like <a href="https://fmhy.net/internet-tools#firefox-extensions" target="_blank" rel="noreferrer">ContextSearch web-ext</a>.</p></li><li><p>Unstarred <a href="https://fmhy.net/file-tools#file-managers" target="_blank" rel="noreferrer">Files</a> in File Managers. There was a lot of hype for this originally, but people have started to come forward saying it&#39;s too laggy / slow to be useful.</p></li><li><p>Unstarred Grok, Qwen, Mage, and Flux.1 Schnell in <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Image Gen</a>. These were considered good in the past, but there are much better, less-dated free options at this point.</p></li></ul>',9))])}const u=t(l,[["render",d]]);export{b as __pageData,u as default};
